import os
import subprocess

from .resolve import resolve


def run(argv, timeout=None):
    """解析 ``argv[0]`` 并执行，返回 ``subprocess.CompletedProcess``。"""
    if not argv:
        raise ValueError("argv must not be empty")

    path = resolve(argv[0])

    # 检查文件扩展名，判断是否需要通过 cmd.exe 执行
    _, ext = os.path.splitext(path)
    ext_lower = ext.lower()

    # .bat 和 .cmd 必须通过命令解释器启动
    if ext_lower in (".bat", ".cmd"):
        # 使用 cmd.exe /c 启动批处理脚本
        # 保留原始参数，cmd.exe 会正确处理脚本的退出码
        cmd_argv = ["cmd.exe", "/c", path] + [str(a) for a in argv[1:]]
        return subprocess.run(
            cmd_argv,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    else:
        # .exe 和其他可执行文件直接启动
        return subprocess.run(
            [path] + [str(a) for a in argv[1:]],
            capture_output=True,
            text=True,
            timeout=timeout,
        )


def run_ok(argv, timeout=None):
    """执行并断言成功；返回标准输出（已去掉尾部空白）。"""
    proc = run(argv, timeout=timeout)
    if proc.returncode != 0:
        raise RuntimeError(
            "command %r exited with %d: %s" % (argv[0], proc.returncode, proc.stderr.strip())
        )
    return proc.stdout.strip()
